#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google service account for the Miss B Modal listener.
# Run: ./scripts/google-sa-wizard.sh
# Writes only GOOGLE_PROJECT_ID and GOOGLE_SA_EMAIL to missb-app/.env.
# The JSON key is stored in Modal secret missb-google-sa and nowhere else.
# ──────────────────────────────────────────────────────────────────────────

# Keep these in sync with scripts/verify-google-sa.py.
SPREADSHEET_ID="1deoDnkmTk72Hl43irxqc5fX-pW_qOPWCF-AxLHRk96M"
SECRET_NAME="missb-google-sa"
MODAL_PROFILE_WANTED="adrianp916"

APP_ROOT="$(cd "$(dirname "$0")/.." && pwd -P)"
ENV_FILE="$APP_ROOT/.env"
VERIFY_PY="$APP_ROOT/scripts/verify-google-sa.py"
DOWNLOADS="${HOME}/Downloads"

GOOGLE_SA_KEY_PATH=""
SECRET_READY=0
UPLOADED_THIS_RUN=0
VERIFIED=0

TOTAL_STAGES=7

# Newest regular *.json directly inside a directory, or empty.
newest_json() {
  local dir="$1" newest="" newest_mtime=0 f mtime
  [[ -d "$dir" && -r "$dir" ]] || return 0
  for f in "$dir"/*.json; do
    [[ -f "$f" ]] || continue
    if ! mtime=$(file_mtime "$f"); then
      continue
    fi
    if (( mtime > newest_mtime )); then
      newest=$f
      newest_mtime=$mtime
    fi
  done
  printf '%s' "$newest"
}

file_mtime() {
  local f="$1"
  if [[ "$(uname -s)" == "Darwin" ]]; then
    stat -f '%m' "$f"
  else
    stat -c '%Y' "$f"
  fi
}

trim() {
  local s="$1"
  s="${s#"${s%%[![:space:]]*}"}"
  s="${s%"${s##*[![:space:]]}"}"
  printf '%s' "$s"
}

# Expand a leading ~ and one layer of matching quotes. Leave other text as typed.
normalize_path() {
  local p
  p=$(trim "$1")
  case "$p" in
    \"*\") p="${p#\"}"; p="${p%\"}" ;;
    \'*\') p="${p#\'}"; p="${p%\'}" ;;
  esac
  case "$p" in
    \~) p="$HOME" ;;
    \~/*) p="$HOME/${p#\~/}" ;;
  esac
  if [[ -n "$p" && ! -e "$p" && -e "${p//\\ / }" ]]; then
    p="${p//\\ / }"
  fi
  printf '%s' "$p"
}

abs_path() {
  python3 -c 'import os, sys; print(os.path.abspath(sys.argv[1]))' "$1"
}

# True when the file's real location sits inside the app repo.
path_in_app() {
  local abs
  abs=$(python3 -c 'import os, sys; print(os.path.realpath(sys.argv[1]))' "$1") || return 1
  case "$abs/" in
    "$APP_ROOT/"*) return 0 ;;
  esac
  return 1
}

looks_like_project_id() {
  [[ "$1" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]]
}

looks_like_sa_email() {
  [[ "$1" =~ ^[a-z0-9-]+@[a-z0-9-]+\.iam\.gserviceaccount\.com$ ]]
}

# mode is "identity" (email<TAB>project_id) or "compact" (one-line JSON).
# Private key material is never written to stderr.
sa_key_tool() {
  python3 - "$1" "$2" <<'PY'
import json
import sys

mode, path = sys.argv[1], sys.argv[2]
try:
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
except Exception as exc:
    sys.stderr.write("could not read JSON: %s\n" % exc)
    sys.exit(1)
if not isinstance(data, dict) or data.get("type") != "service_account":
    sys.stderr.write("file is not a Google service-account JSON key\n")
    sys.exit(1)
email = data.get("client_email") or ""
project = data.get("project_id") or ""
private_key = data.get("private_key") or ""
if not isinstance(email, str) or not email or not isinstance(private_key, str) or not private_key:
    sys.stderr.write("key JSON is missing client_email or private_key\n")
    sys.exit(1)
if mode == "identity":
    sys.stdout.write(email + "\t" + project)
elif mode == "compact":
    sys.stdout.write(json.dumps(data, separators=(",", ":")))
else:
    sys.stderr.write("unknown mode\n")
    sys.exit(2)
PY
}

# Exit 0 when SECRET_NAME is listed, 1 when the list parsed and it is absent,
# 2 when the list command or its JSON could not be read.
secret_listed() {
  local raw
  raw=$(modal secret list --json) || return 2
  printf '%s' "$raw" | python3 -c '
import json
import re
import sys

want = sys.argv[1]
raw = re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", sys.stdin.read())
start, end = raw.find("["), raw.rfind("]")
if start < 0 or end < start:
    sys.exit(2)
try:
    data = json.loads(raw[start:end + 1])
except json.JSONDecodeError:
    sys.exit(2)
if not isinstance(data, list):
    sys.exit(2)
names = []
for row in data:
    if isinstance(row, dict):
        names.append(str(row.get("Name", "")))
sys.exit(0 if want in names else 1)
' "$SECRET_NAME"
}

# Upload the key file. force is "yes" or "no".
# --from-json is the wrong shape: it would publish each field of the key
# (type, private_key, client_email, ...) instead of one GOOGLE_SA_JSON value.
create_modal_secret() {
  local path="$1" force="$2" payload
  payload=$(sa_key_tool compact "$path") || return 1
  if [[ "$force" == "yes" ]]; then
    modal secret create --force "$SECRET_NAME" "GOOGLE_SA_JSON=${payload}" || {
      unset payload
      return 1
    }
  else
    modal secret create "$SECRET_NAME" "GOOGLE_SA_JSON=${payload}" || {
      unset payload
      return 1
    }
  fi
  unset payload
  return 0
}

banner "Google Sheets access — Miss B"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Google Cloud project"
say "The listener's service account lives in a Google Cloud project."
say "Create one for Miss B, or reuse a project you already have."
saved_project=$(_existing GOOGLE_PROJECT_ID || true)
saved_project_lc=$(printf '%s' "$saved_project" | tr '[:upper:]' '[:lower:]')
if [[ -n "$saved_project" ]]; then
  note "Saved project id: $saved_project"
  say "Enter keeps that id. Open the dashboard only if you want to check it."
fi
if looks_like_project_id "$saved_project_lc"; then
  open_url "https://console.cloud.google.com/home/dashboard?project=${saved_project_lc}"
else
  open_url "https://console.cloud.google.com/projectcreate"
fi
step "Sign in with the Google account that should own the project."
step "To create: set the project name (for example, Miss B)."
step "Copy the project id, not the display name. The id may sit behind an"
step "Edit control. It is lowercase letters, digits, and hyphens."
step "The button may be named Create or Create project."
step "To reuse a project: use the project picker in the top bar, or the ID"
step "column at https://console.cloud.google.com/cloud-resource-manager"
while true; do
  ask GOOGLE_PROJECT_ID "Project id:"
  GOOGLE_PROJECT_ID=$(printf '%s' "$(trim "$GOOGLE_PROJECT_ID")" | tr '[:upper:]' '[:lower:]')
  if [[ -z "$GOOGLE_PROJECT_ID" ]]; then
    warn "A project id is required."
    continue
  fi
  case "$GOOGLE_PROJECT_ID" in
    *$'\n'*|*$'\r'*) warn "That value contains a line break."; continue ;;
  esac
  if looks_like_project_id "$GOOGLE_PROJECT_ID"; then
    break
  fi
  warn "That does not look like a project id (6–30 chars, starts with a letter)."
  if confirm "Use it anyway?"; then
    break
  fi
done
write_env GOOGLE_PROJECT_ID "$GOOGLE_PROJECT_ID"
pause "Press Enter to continue."

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Enable the Sheets API"
say "The service account can call only APIs that are turned on for this project."
open_url "https://console.cloud.google.com/apis/library/sheets.googleapis.com?project=${GOOGLE_PROJECT_ID}"
step "Confirm the project picker shows ${GOOGLE_PROJECT_ID}."
step "Click Enable. If the page already says the API is enabled, or the"
step "button says Manage, leave it. Enabling twice does nothing."
pause "Press Enter when the Google Sheets API is enabled."

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Service account"
say "Sheets access comes from sharing the spreadsheet, not from IAM roles."
say "Do not grant this account any project role."
saved_email=$(_existing GOOGLE_SA_EMAIL || true)
if [[ -n "$saved_email" ]]; then
  note "Saved service account email: $saved_email"
  say "Enter keeps that email if it is still the one you want."
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${GOOGLE_PROJECT_ID}"
  step "If that email is already in the list, copy it and move on."
  step "Otherwise create one. The button may be named Create service account."
else
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=${GOOGLE_PROJECT_ID}"
fi
step "Service account name: missb-listener"
step "The service account ID fills in from the name. Leave it."
step "Create and continue. On the role screen, add nothing, then Continue"
step "or Skip. On the next screen, add nothing, then Done."
step "Button labels may be Create and continue, Continue, Skip, or Done."
step "Copy the email from the list. It should look like:"
note "  missb-listener@${GOOGLE_PROJECT_ID}.iam.gserviceaccount.com"
while true; do
  ask GOOGLE_SA_EMAIL "Service account email:"
  GOOGLE_SA_EMAIL=$(printf '%s' "$(trim "$GOOGLE_SA_EMAIL")" | tr '[:upper:]' '[:lower:]')
  if [[ -z "$GOOGLE_SA_EMAIL" ]]; then
    warn "The service account email is required."
    continue
  fi
  case "$GOOGLE_SA_EMAIL" in
    *$'\n'*|*$'\r'*) warn "That value contains a line break."; continue ;;
  esac
  if looks_like_sa_email "$GOOGLE_SA_EMAIL"; then
    break
  fi
  warn "That does not look like a service account email."
  if confirm "Use it anyway?"; then
    break
  fi
done
write_env GOOGLE_SA_EMAIL "$GOOGLE_SA_EMAIL"
pause "Press Enter to continue."

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Download the JSON key"
say "Google shows a private key only at download time. You can create another"
say "key later; a new key does not revoke the old one. Delete old keys in"
say "this Keys list only after Modal is storing the one you still want."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${GOOGLE_PROJECT_ID}"
step "Click ${GOOGLE_SA_EMAIL}."
step "Open the Keys tab (it may be labeled Keys or KEYS)."
step "Add key, then Create new key. Choose JSON, not P12."
step "The confirm button may be named Create. Wait until the file finishes"
step "downloading. It usually lands in ~/Downloads."
note "Type skip if Modal already has this key and the file is gone."
pause "Press Enter when the download has finished, or to skip."
while true; do
  suggest=$(newest_json "$DOWNLOADS")
  if [[ -n "$suggest" ]]; then
    stamp=$(date -r "$suggest" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || true)
    bytes=$(wc -c < "$suggest" | tr -d '[:space:]')
    note "Newest .json in ~/Downloads (Enter uses this):"
    note "  $suggest"
    note "  ${stamp:-unknown time}, ${bytes} bytes"
    if mtime=$(file_mtime "$suggest"); then
      now=$(date +%s)
      if (( now - mtime > 7200 )); then
        warn "That file is more than 2 hours old. Confirm it is the key you just downloaded."
      fi
    fi
  else
    note "No .json files in ~/Downloads. Paste a path, or type skip."
  fi
  ask GOOGLE_SA_KEY_PATH "JSON key path:"
  typed=$(trim "$GOOGLE_SA_KEY_PATH")
  typed_lc=$(printf '%s' "$typed" | tr '[:upper:]' '[:lower:]')
  if [[ "$typed_lc" == "skip" ]]; then
    GOOGLE_SA_KEY_PATH=""
    note "Continuing without a key file."
    break
  fi
  GOOGLE_SA_KEY_PATH=$(normalize_path "$typed")
  if [[ -z "$GOOGLE_SA_KEY_PATH" && -n "$suggest" ]]; then
    GOOGLE_SA_KEY_PATH=$suggest
    note "Using $GOOGLE_SA_KEY_PATH"
  fi
  if [[ -z "$GOOGLE_SA_KEY_PATH" ]]; then
    if confirm "No file given. Continue without a key file?"; then
      GOOGLE_SA_KEY_PATH=""
      break
    fi
    continue
  fi
  if [[ -d "$GOOGLE_SA_KEY_PATH" ]]; then
    picked=$(newest_json "$GOOGLE_SA_KEY_PATH")
    if [[ -z "$picked" ]]; then
      warn "No .json files in that directory."
      continue
    fi
    GOOGLE_SA_KEY_PATH=$picked
    note "Using newest .json in that directory: $GOOGLE_SA_KEY_PATH"
  fi
  if [[ ! -f "$GOOGLE_SA_KEY_PATH" ]]; then
    warn "No file at that path."
    continue
  fi
  GOOGLE_SA_KEY_PATH=$(abs_path "$GOOGLE_SA_KEY_PATH")
  if path_in_app "$GOOGLE_SA_KEY_PATH"; then
    warn "That file is inside the repo ($APP_ROOT)."
    warn "Move it out, for example to ~/Downloads. The key must not be committed."
    continue
  fi
  if ! meta=$(sa_key_tool identity "$GOOGLE_SA_KEY_PATH"); then
    warn "That file is not a usable service-account key."
    continue
  fi
  key_email=${meta%%$'\t'*}
  key_project=${meta#*$'\t'}
  key_email=$(printf '%s' "$key_email" | tr '[:upper:]' '[:lower:]')
  key_project=$(printf '%s' "$key_project" | tr '[:upper:]' '[:lower:]')
  if [[ "$key_email" != "$GOOGLE_SA_EMAIL" ]]; then
    warn "Key client_email is $key_email"
    warn "Saved email is $GOOGLE_SA_EMAIL"
    if confirm "Use the email from the key file?"; then
      GOOGLE_SA_EMAIL=$key_email
      write_env GOOGLE_SA_EMAIL "$GOOGLE_SA_EMAIL"
    else
      note "Keeping the email you typed. Share that exact address."
    fi
  fi
  if [[ -n "$key_project" && "$key_project" != "$GOOGLE_PROJECT_ID" ]]; then
    warn "Key project_id is $key_project"
    warn "Saved project id is $GOOGLE_PROJECT_ID"
    if confirm "Use the project id from the key file?"; then
      GOOGLE_PROJECT_ID=$key_project
      write_env GOOGLE_PROJECT_ID "$GOOGLE_PROJECT_ID"
    fi
  fi
  say "Key file accepted for $key_email"
  break
done
pause "Press Enter to continue."

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Store the key in Modal"
say "The JSON is stored as Modal secret ${SECRET_NAME}, under the key name"
say "GOOGLE_SA_JSON. Nothing from the key file is written to .env."
note "Commands use profile ${MODAL_PROFILE_WANTED} and its default environment."
note "If Modal complains about multiple environments, export MODAL_ENVIRONMENT"
note "to the one you want and re-run. This wizard does not pass --env."
if ! command -v modal >/dev/null 2>&1; then
  warn "modal is not on PATH."
  note "Install the Modal CLI, activate profile ${MODAL_PROFILE_WANTED}, and re-run."
  SKIPPED+=("Modal secret ${SECRET_NAME} (modal CLI missing)")
else
  profile=$(modal profile current 2>/dev/null || true)
  profile=$(trim "$profile")
  if [[ "$profile" != "$MODAL_PROFILE_WANTED" ]]; then
    warn "Active Modal profile is '${profile:-unknown}', not ${MODAL_PROFILE_WANTED}."
    step "Run: modal profile activate ${MODAL_PROFILE_WANTED}"
    pause "Press Enter after activating profile ${MODAL_PROFILE_WANTED}."
    profile=$(modal profile current 2>/dev/null || true)
    profile=$(trim "$profile")
  fi
  if [[ "$profile" != "$MODAL_PROFILE_WANTED" ]]; then
    warn "Refusing to write a secret from profile '${profile:-unknown}'."
    SKIPPED+=("Modal secret ${SECRET_NAME} (active profile is not ${MODAL_PROFILE_WANTED})")
  else
    say "Active Modal profile: ${MODAL_PROFILE_WANTED}."
    exists=0
    if secret_listed; then
      exists=1
      say "Secret ${SECRET_NAME} already exists."
    else
      list_status=$?
      if [[ "$list_status" -eq 1 ]]; then
        say "Secret ${SECRET_NAME} is not in the list yet."
      else
        warn "Could not read modal secret list --json."
        note "If create says the secret already exists, re-run and confirm overwrite."
      fi
    fi
    if [[ -z "$GOOGLE_SA_KEY_PATH" ]]; then
      if [[ "$exists" -eq 1 ]]; then
        say "No new key file. Leaving the existing secret in place."
      else
        warn "No key file, and ${SECRET_NAME} is not in the list."
        note "Re-run and point at the downloaded JSON."
        SKIPPED+=("Modal secret ${SECRET_NAME} (no key file)")
      fi
    elif [[ "$exists" -eq 1 ]]; then
      say "This CLI overwrites with --force, so delete-then-create is unnecessary."
      if confirm "Overwrite ${SECRET_NAME} with this key file?"; then
        say "Running: modal secret create --force ${SECRET_NAME} GOOGLE_SA_JSON=<key file>"
        if create_modal_secret "$GOOGLE_SA_KEY_PATH" yes; then
          UPLOADED_THIS_RUN=1
          say "Modal accepted the secret."
        else
          warn "modal secret create --force failed."
          SKIPPED+=("Modal secret ${SECRET_NAME} (create --force failed)")
        fi
      else
        say "Keeping the existing secret."
      fi
    else
      say "Running: modal secret create ${SECRET_NAME} GOOGLE_SA_JSON=<key file>"
      if create_modal_secret "$GOOGLE_SA_KEY_PATH" no; then
        UPLOADED_THIS_RUN=1
        say "Modal accepted the secret."
      else
        warn "modal secret create failed."
        note "If the error says it already exists, re-run and confirm overwrite."
        SKIPPED+=("Modal secret ${SECRET_NAME} (create failed)")
      fi
    fi
    say "Checking modal secret list (names only; values are not shown):"
    if modal secret list; then
      if secret_listed; then
        SECRET_READY=1
        say "Confirmed: ${SECRET_NAME} is listed."
      else
        warn "${SECRET_NAME} is still not listed."
        SECRET_READY=0
        SKIPPED+=("${SECRET_NAME} missing from modal secret list")
      fi
    else
      warn "modal secret list failed."
      SKIPPED+=("Confirm ${SECRET_NAME} via modal secret list")
    fi
  fi
fi
pause "Press Enter to continue."

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "Share the spreadsheet"
say "The service account can edit the audit sheet only after you share it."
say "If this sheet lives under a different Google login than the Cloud"
say "project, switch to the account that can share the sheet."
open_url "https://docs.google.com/spreadsheets/d/${SPREADSHEET_ID}/edit"
step "Click Share (top right; the button may be named Share)."
step "Add this address, and set the role to Editor:"
printf '  %s%s%s\n' "$BOLD" "$GOOGLE_SA_EMAIL" "$RESET"
if command -v pbcopy >/dev/null 2>&1 && printf '%s' "$GOOGLE_SA_EMAIL" | pbcopy; then
  note "Copied that email to the clipboard."
else
  note "Copy the email above into the share box."
fi
step "Uncheck Notify people if you see it (a service account has no inbox)."
step "Confirm. The button may be named Share, Send, or Done."
step "If that email is already listed as Editor, you are done."
pause "Press Enter when ${GOOGLE_SA_EMAIL} is an Editor on the sheet."

# ── Stage 7 ────────────────────────────────────────────────────────────────
stage "Verify access and remove the local key"
say "This reads spreadsheet metadata with the service account key only."
say "It checks the tab \"missb app automated input\" (sheetId 1966196459)."
note "It does not write to the sheet."
if [[ -z "$GOOGLE_SA_KEY_PATH" ]]; then
  warn "No key file on hand, so the live read is skipped."
  note "Re-run while the JSON is still on disk, or later:"
  note "  uv run --with google-auth \"$VERIFY_PY\" /path/to/key.json"
  SKIPPED+=("Sheets verification (no local key file)")
elif [[ ! -f "$VERIFY_PY" ]]; then
  warn "Missing $VERIFY_PY"
  SKIPPED+=("Sheets verification (script missing)")
elif ! command -v uv >/dev/null 2>&1; then
  warn "uv is not on PATH, so the Sheets check cannot run."
  note "Install uv, then re-run. Equivalent command:"
  note "  uv run --with google-auth \"$VERIFY_PY\" \"$GOOGLE_SA_KEY_PATH\""
  SKIPPED+=("Sheets verification (uv missing)")
else
  note "The first run may spend a minute downloading google-auth."
  if uv run --with google-auth "$VERIFY_PY" "$GOOGLE_SA_KEY_PATH"; then
    VERIFIED=1
    say "Verification succeeded."
  else
    warn "Verification failed."
    note "API disabled: repeat the Sheets API stage, then re-run."
    note "Permission denied: the service account is not an Editor yet."
    note "The key file was left in place."
    SKIPPED+=("Sheets verification failed")
  fi
fi
if [[ "$VERIFIED" -eq 1 && "$UPLOADED_THIS_RUN" -eq 1 && "$SECRET_READY" -eq 1 ]]; then
  say "Local key file: $GOOGLE_SA_KEY_PATH"
  if [[ -L "$GOOGLE_SA_KEY_PATH" ]]; then
    warn "That path is a symlink. Deleting it removes the link, not the target."
  fi
  if confirm "Delete that local key file now? The JSON is in Modal secret ${SECRET_NAME}."; then
    rm -f -- "$GOOGLE_SA_KEY_PATH"
    if [[ -e "$GOOGLE_SA_KEY_PATH" ]]; then
      warn "Could not delete $GOOGLE_SA_KEY_PATH"
      SKIPPED+=("Delete the local key file")
    else
      say "Deleted the local key file."
    fi
  else
    warn "Left the key file on disk: $GOOGLE_SA_KEY_PATH"
    SKIPPED+=("Local key file still on disk")
  fi
elif [[ "$VERIFIED" -eq 1 && -n "$GOOGLE_SA_KEY_PATH" ]]; then
  note "Left the key file on disk because this run did not store it in Modal."
  note "$GOOGLE_SA_KEY_PATH"
fi
pause "Press Enter to finish."

finish
